import React from 'react'
import { assets } from '../assets/assets'

function Dashboard() {
  return (
    <div className="dashboard-container">
      <img className="dashboard-img" src={assets.ComingSoon} alt="comingSoon" />
    </div>
  )
}


export default Dashboard
